def separate_paren_groups(paren_string: str) -> List[str]:
    # Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Initialize an empty list to store separate groups
    separate_groups = []

    # Iterate through the input string
    i = 0
    while i < len(paren_string):
        # Identify and extract each group of nested parentheses
        if paren_string[i] == '(':
            count = 1
            j = i + 1
            while j < len(paren_string):
                if paren_string[j] == '(':
                    count += 1
                elif paren_string[j] == ')':
                    count -= 1
                if count == 0:
                    separate_groups.append(paren_string[i:j+1])
                    i = j
                    break
                j += 1
        i += 1

    # Check if each group is balanced (properly closed) and not nested within each other
    balanced_groups = []
    for group in separate_groups:
        stack = []
        is_balanced = True
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack[-1] != '(':
                    is_balanced = False
                    break
                stack.pop()
        if is_balanced and not any('(' in g for g in balanced_groups):
            balanced_groups.append(group)

    return balanced_groups
